WITH filtered AS (SELECT *, DATEDIFF(CURRENT_DATE(), order_date) AS days_since_order_date, amount - shipping_fee AS amount_with_shipping, COALESCE(channel, 'N/A') AS resolved_channel FROM orders WHERE order_date >= DATE '2023-03-25') SELECT s.*, latest.shipment_status, latest.shipment_carrier FROM filtered s LEFT JOIN LATERAL (SELECT c.status AS shipment_status, c.carrier AS shipment_carrier FROM shipments c WHERE c.order_id = s.id ORDER BY c.delivered_date DESC, c.id DESC LIMIT 1) latest ON TRUE
